export const ICON_NAMES = Object.keys(ICONS);

const attr = o => Object.entries(o).map(([k, v]) => ` ${k}="${String(v).replace(/"/g, '&quot;')}"`).join('');

export function icon(name, { size = 16, cls = '' } = {}) {
  const nodes = ICONS[name];
  if (!nodes) { console.warn('[lk-icons] unknown icon:', name); return ''; }
  const body = nodes.map(([tag, a]) => `<${tag}${attr(a)}/>`).join('');
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lk-icon${cls ? ' ' + cls : ''}" aria-hidden="true">${body}</svg>`;
}
